{
  "declined": "none",
  "criteria": [
    {
      "id": "task",
      "score": 3,
      "reason": "作者完成邀請的任務，語氣也友善 (e.g. \"I want to invite you come to Taiwan in next summer.\"、\"Please tell me when you can come\"). 但有些表達不夠自然或完整，未完全符合目標字數範圍的流暢度與細節。"
    },
    {
      "id": "organization",
      "score": 3,
      "reason": "信件有開頭、主體和結尾段落的基本結構 (例如問候、行程建議、住宿安排、結尾)，但段落內句子連接不夠順暢，像是\"Jiufen is very old street it have many tea house.\"。"
    },
    {
      "id": "vocabulary",
      "score": 3,
      "reason": "詞彙多為日常用語 (\"delicious food\", \"the beach\", \"sunscreen\")，但有些字詞使用不當或重複，像是\"have many delicious food\"和\"tea house\"單複數及搭配需改進。"
    },
    {
      "id": "grammar",
      "score": 2,
      "reason": "句子文法錯誤頻繁，例如缺少介詞/不定詞、主謂不一致與冠詞問題，如\"I want to invite you come\"、\"Taiwan is very beautiful and have many\"、\"my parents is very welcome you\"。"
    }
  ],
  "issues": [
    {
      "quote": "I want to invite you come to Taiwan in next summer.",
      "type": "grammar",
      "why": "這句缺少介詞或不定詞結構，且時間片語順序與冠詞不自然，應使用固定說法如 'next summer' 前不用 'in' 或用 'in the next summer' 不常見。",
      "suggestion": "I want to invite you to come to Taiwan next summer."
    },
    {
      "quote": "Taiwan is very beautiful and have many delicious food.",
      "type": "grammar",
      "why": "主詞與動詞不一致，Taiwan 為單數，應用 'has'；此外 'many delicious food' 應改為可數或不可數正確搭配。",
      "suggestion": "Taiwan is very beautiful and has a lot of delicious food."
    },
    {
      "quote": "Jiufen is very old street it have many tea house.",
      "type": "sentence",
      "why": "這是兩個獨立子句錯誤連接，且名詞單複數與冠詞用錯，語意不清楚。",
      "suggestion": "Jiufen is an old street with many teahouses."
    }
  ],
  "more": [
    {
      "quote": "I can bring you go to Taipei 101 and Jiufen.",
      "type": "preposition",
      "why": "中文式英語直接翻譯造成介系詞或動詞搭配錯誤，應使用 'take you to' 或 'show you' 類型表達。",
      "suggestion": "I can take you to Taipei 101 and Jiufen."
    },
    {
      "quote": "We also can go to the beach in Kenting, but summer in Taiwan is very hot so you must to bring the sunscreen.",
      "type": "verb",
      "why": "'must to bring' 為不正確結構；而且句子過長缺少逗號分隔，'the sunscreen' 冠詞用法視情境可省略。",
      "suggestion": "We can also go to the beach in Kenting, but summer in Taiwan is very hot so you must bring sunscreen."
    },
    {
      "quote": "You can live in my home, my parents is very welcome you.",
      "type": "grammar",
      "why": "逗號拼接兩個獨立句應改成兩句或用連接詞；'parents is' 主謂不一致；'welcome you' 用法需調整為 'welcome you' 但前置詞或句型更自然為 'my parents will welcome you'。",
      "suggestion": "You can stay at my home; my parents will welcome you."
    },
    {
      "quote": "Please tell me when you can come and I go to airport to pick you.",
      "type": "grammar",
      "why": "動詞時態與結構不完整，'I go to airport to pick you' 應改為未來意向的完整說法且加上冠詞。",
      "suggestion": "Please tell me when you can come and I will go to the airport to pick you up."
    },
    {
      "quote": "Hope see you soon!",
      "type": "grammar",
      "why": "缺少主詞與助動詞，口語可接受但書信中應完整表達。",
      "suggestion": "Hope to see you soon!"
    }
  ],
  "strengths": [
    {
      "quote": "How are you? Long time no see.",
      "why": "開場問候自然，符合朋友間非正式電子郵件的語氣，表達親切。"
    },
    {
      "quote": "We also can go to the beach in Kenting",
      "why": "提出具體活動建議（Kenting、海灘），讓邀請更具吸引力與可行性。"
    }
  ],
  "summary": "你的信表達意圖明確且語氣友善，接下來請集中修正動詞與句子結構錯誤（像是不定詞、主謂一致和冠詞），並改善句子連接使段落更流暢。練習把句子拆成簡單、正確的句子後再用連接詞串接，會大幅提升自然度。"
}
